cat > tb.sv <<'TB'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg valid_in = 0;
  reg [7:0] data_in = 0;
  wire valid_out;
  wire [15:0] data_out;

  TopModule dut(
    .clk(clk), .rst_n(rst_n), .valid_in(valid_in), .data_in(data_in),
    .valid_out(valid_out), .data_out(data_out)
  );

  always #5 clk = ~clk;

  task send(input [7:0] b);
    begin
      @(negedge clk);
      valid_in = 1;
      data_in = b;
      @(negedge clk);
      valid_in = 0;
    end
  endtask

  initial begin
    repeat (2) @(negedge clk);
    rst_n = 1;

    send(8'"'h12);
    if (valid_out "'!== 1'"'b0) begin
      "'$display("FAIL: valid_out asserted after one byte");
      $finish(1);
    end

    send(8'"'h34);
    @(posedge clk);
    #1;
    if (valid_out "'!== 1'"'b1 || data_out "'!== 16'"'h1234) begin
      "'$display("FAIL: expected 1234/1 got %h/%b", data_out, valid_out);
      $finish(1);
    end

    @(posedge clk);
    #1;
    if (valid_out !== 1'"'b0) begin
      "'$display("FAIL: valid_out did not clear");
      $finish(1);
    end

    send(8'"'hAB);
    send(8'hCD);
    @(posedge clk);
    #1;
    if (valid_out "'!== 1'"'b1 || data_out "'!== 16'"'hABCD) begin
      "'$display("FAIL: expected ABCD/1 got %h/%b", data_out, valid_out);
      $finish(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
TB

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

